def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    last_me, last_opp = history[-1]
    opp_c = sum(1 for _, o in history if o == 'C')
    opp_d = n - opp_c
    my_d = sum(1 for m, _ in history if m == 'D')

    w5 = 5 if n >= 5 else n
    recent5_c = sum(1 for _, o in history[-w5:] if o == 'C')
    recent5_d = w5 - recent5_c

    w10 = 10 if n >= 10 else n
    recent10_c = sum(1 for _, o in history[-w10:] if o == 'C')
    recent10_d = w10 - recent10_c

    punished_switch = 0
    unpunished = 0
    same_dc = 0
    for i in range(n):
        m, o = history[i]
        if m == 'D' and o == 'C':
            same_dc += 1
        if i + 1 < n and m == 'D':
            if history[i + 1][1] == 'D':
                if o == 'C':
                    punished_switch += 1
            else:
                unpunished += 1

    if n < 10:
        if last_opp == 'D':
            if recent10_d >= 3:
                return 'D'
            if opp_c >= 2:
                return 'C'
            if opp_d <= 1:
                return 'C'
            return 'D'
        return 'C'

    if opp_c == 0 and opp_d >= 2:
        return 'D'
    if opp_c <= 2 and opp_d >= 4:
        return 'D'
    if recent10_c <= 2 and opp_d >= 4:
        return 'D'

    if (
        my_d == 0
        and punished_switch == 0
        and recent10_c >= 10
        and opp_c >= opp_d
        and opp_d <= 6
        and n >= 25
    ):
        return 'D'

    if (
        same_dc >= 1
        and unpunished >= 1
        and punished_switch == 0
        and recent10_c >= 8
        and opp_c >= opp_d
        and opp_d <= 8
    ):
        if last_opp == 'C':
            return 'D'
        if last_opp == 'D' and recent10_d <= 3:
            return 'D'

    if recent5_d >= 5:
        return 'D'

    if n >= 20:
        recent20_c = sum(1 for _, o in history[-20:] if o == 'C')
        if recent20_c <= 12:
            return 'D'

    if recent10_d >= 8:
        return 'D'

    if n >= 96 and last_opp == 'D':
        return 'D'

    if recent10_c >= 9:
        return 'C'

    opp_rate = opp_c / n

    if opp_rate >= 0.8:
        return 'C'
    if opp_rate <= 0.3:
        return 'D'

    if last_opp == 'D':
        if last_me == 'C':
            if opp_rate > 0.55 and recent10_d <= 4:
                return 'C'
            return 'D'
        if opp_rate > 0.55 and recent10_c >= 2 and recent10_d <= 6:
            return 'C'
        return 'D'

    if last_me == 'D':
        if opp_rate > 0.85 and recent10_c >= 9 and punished_switch == 0:
            return 'D'
        return 'C'

    if n >= 20:
        last20 = history[-20:]
        d_after_d = sum(
            1 for i in range(1, len(last20))
            if last20[i - 1][1] == 'D' and last20[i][1] == 'D'
        )
        if d_after_d >= 5:
            return 'D'

    if opp_rate > 0.5:
        return 'C'
    if recent5_c >= 3:
        return 'C'

    return 'D' if rng.random() < 0.5 else 'C'
